        return []

    min_even = None
    result_idx = -1

    for idx, val in enumerate(arr):
        if val % 2 == 0:  # even number
            if (min_even is None) or (val < min_even):
                min_even = val
                result_idx = idx

    if min_even is not None:
        return [min_even, result_idx]
