def search(lst):
    # Count the frequency of each integer in the list
    freq = {}
    for x in lst:
        freq[x] = freq.get(x, 0) + 1

    # Find the greatest integer whose frequency is at least its value
    result = -1
    for num, count in freq.items():
        if num > 0 and count >= num:
            if num > result:
                result = num

    return result
```

