def split_words(txt):
    # Check if there are any whitespace characters
    if any(c.isspace() for c in txt):
        return txt.split()

    # If no whitespaces, check for commas
    if ',' in txt:
        return [word.strip() for word in txt.split(',')]

    # No whitespaces and no commas - count lower-case letters with odd positions (1, 3, 5, ...)
    count = 0
    for char in txt:
        if 'a' <= char <= 'z':
            position = ord(char) - ord('a')
            if position % 2 == 1:
                count += 1
    return count
```

