def prod_signs(arr):
    if not arr:
        return None

    magnitude_sum = 0
    sign_product = 1

    for num in arr:
        # Determine the sign of the current number
        if num > 0:
            sign = 1
        elif num < 0:
            sign = -1
        else:
            sign = 0

        magnitude_sum += abs(num)

        # If we encounter a zero, the product of signs becomes 0 and stays 0
        if sign == 0:
            break

        sign_product *= sign

    return magnitude_sum * sign_product
```

